  function normalizeLanguage(value) {
    const raw = String(value || "").trim().toLowerCase().replace(/_/g, "-");
    if (!raw || raw === "system" || raw === "auto") return "system";
    const base = raw.split("-")[0];
    return SUPPORTED.includes(base) ? base : "en";
  }

  function detectLanguage() {
    if (typeof location !== "undefined") {
      const requested = new URLSearchParams(location.search).get("lang");
      const normalized = normalizeLanguage(requested);
      if (requested && normalized !== "system") return normalized;
    }
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      const normalized = normalizeLanguage(saved);
      if (saved && normalized !== "system") return normalized;
    } catch (err) {
      // Storage is optional.
    }
    const browserLanguage = typeof navigator !== "undefined" ? navigator.language : "en";
    const detected = normalizeLanguage(browserLanguage);
    return detected === "system" ? "en" : detected;
  }

